<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Snake Game</title>
  <style>
    :root {
      --bg-color: #2c3e50;
      --board-bg: #34495e;
      --snake-head: #2ecc71;
      --snake-body: #27ae60;
      --food-color: #e74c3c;
      --text-color: #ecf0f1;
      --btn-hover: #1abc9c;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-color);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
    }

    h1 {
      margin-bottom: 20px;
    }

    #game-container {
      position: relative;
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    #score {
      font-size: 24px;
      margin-bottom: 15px;
      min-width: 180px;
      text-align: center;
      padding: 10px 0;
      background-color: rgba(0, 0, 0, 0.3);
      border-radius: 8px;
    }

    #snake {
      width: 400px;
      height: 400px;
      background-color: var(--board-bg);
      border-radius: 8px;
      box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
    }

    #controls {
      display: flex;
      gap: 15px;
      margin-top: 20px;
    }

    .btn {
      padding: 10px 20px;
      font-size: 16px;
      border: none;
      border-radius: 6px;
      background-color: #3498db;
      color: white;
      cursor: pointer;
      transition: background-color 0.2s ease, transform 0.1s ease;
    }

    .btn:hover {
      background-color: var(--btn-hover);
      transform: translateY(-2px);
    }

    .btn:active {
      transform: translateY(1px);
    }

    #pause {
      background-color: #f39c12;
    }

    #reset {
      background-color: #e74c3c;
    }
  </style>
</head>
<body>
  <h1>Snake Game</h1>

  <div id="game-container">
    <div id="score">Score: 0</div>
    <canvas id="snake" width="400" height="400"></canvas>

    <div id="controls">
      <button id="start">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
    </div>
  </div>

  <script>
    // Game constants
    const GRID_SIZE = 20;
    const CELL_SIZE = 400 / GRID_SIZE;

    // Create canvas and context references
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');
    const startBtn = document.getElementById('start');
    const pauseBtn = document.getElementById('pause');
    const resetBtn = document.getElementById('reset');
    const scoreEl = document.getElementById('score');

    // Game state
    let snake = [];
    let food = [0, 0];
    let direction = 'right';
    let nextDirection = 'right';
    let gameInterval = null;
    let isRunning = false;
    let isPaused = false;
    let score = 0;
    let gameOver = false;

    // Initialize the game
    function initGame() {
      snake = [[5, 10], [4, 10], [3, 10]]; // Start with length 3
      direction = 'right';
      nextDirection = 'right';
      score = 0;
      gameOver = false;
      updateScore();
      placeFood();
      draw();
    }

    function startGame() {
      if (!gameInterval) {
        isRunning = true;
        isPaused = false;
        gameInterval = setInterval(gameTick, 150); // ~6.7 FPS
      } else if (isPaused) {
        isPaused = false;
        draw();
      }
    }

    function pauseGame() {
      if (gameInterval && !isPaused) {
        isPaused = true;
        clearInterval(gameInterval);
        gameInterval = null;
        // Draw paused overlay
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = '#fff';
        ctx.font = '30px Arial';
        ctx.textAlign = 'center';
        ctx.fillText("PAUSED", canvas.width / 2, canvas.height / 2 - 15);
        ctx.font = '16px Arial';
        ctx.fillText("Press Start to resume", canvas.width / 2, canvas.height / 2 + 15);
      }
    }

    function resetGame() {
      clearInterval(gameInterval);
      gameInterval = null;
      isRunning = false;
      isPaused = false;
      gameOver = false;
      initGame();
    }

    // Game tick logic
    function gameTick() {
      if (isPaused) return;

      // Update direction from nextDirection to prevent 180-degree turns in one tick
      direction = nextDirection;

      // Calculate new head position
      const [headX, headY] = snake[0];
      let newX = headX;
      let newY = headY;

      switch (direction) {
        case 'up':    newY -= 1; break;
        case 'down':  newY += 1; break;
        case 'left':  newX -= 1; break;
        case 'right': newX += 1; break;
      }

      // Check for collisions
      if (newX < 0 || newX >= GRID_SIZE || newY < 0 || newY >= GRID_SIZE) {
        gameOver = true;
        endGame();
        return;
      }

      const newHead = [newX, newY];

      // Self-collision check
      if (snake.some(segment => segment[0] === newX && segment[1] === newY)) {
        gameOver = true;
        endGame();
        return;
      }

      // Move snake
      snake.unshift(newHead); // Add new head

      // Check for food
      if (newX === food[0] && newY === food[1]) {
        score += 10;
        updateScore();
        placeFood();
      } else {
        snake.pop(); // Remove tail unless we're eating
      }

      draw();
    }

    function endGame() {
      clearInterval(gameInterval);
      gameInterval = null;
      isRunning = false;

      // Draw "GAME OVER" text on canvas
      ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#e74c3c';
      ctx.font = '40px Arial';
      ctx.textAlign = 'center';
      ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 20);

      ctx.fillStyle = '#ecf0f1';
      ctx.font = '20px Arial';
      ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);
    }

    // Place food at a random position not occupied by snake
    function placeFood() {
      let validPosition = false;
      while (!validPosition) {
        const x = Math.floor(Math.random() * GRID_SIZE);
        const y = Math.floor(Math.random() * GRID_SIZE);

        // Check if position is on the snake
        const onSnake = snake.some(segment => segment[0] === x && segment[1] === y);

        if (!onSnake) {
          food = [x, y];
          validPosition = true;
        }
      }
    }

    function draw() {
      // Clear canvas
      ctx.fillStyle = '#34495e'; // Board background color
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw snake
      for (let i = 0; i < snake.length; i++) {
        const [x, y] = snake[i];
        if (i === 0) {
          // Head
          ctx.fillStyle = '#2ecc71'; // Green head
          ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

          // Eyes for the head to make it more visible
          ctx.fillStyle = '#ecf0f1';
          const eyeSize = CELL_SIZE / 5;
          let eyeOffsetX = 0;
          let eyeOffsetY = 0;

          if (direction === 'right') {
            eyeOffsetX = CELL_SIZE - eyeSize * 2;
            eyeOffsetY = CELL_SIZE / 4;
          } else if (direction === 'left') {
            eyeOffsetX = 0;
            eyeOffsetY = CELL_SIZE / 4;
          } else if (direction === 'up') {
            eyeOffsetX = CELL_SIZE / 4;
            eyeOffsetY = 0;
          } else { // down
            eyeOffsetX = CELL_SIZE / 4;
            eyeOffsetY = CELL_SIZE - eyeSize * 2;
          }

          ctx.fillRect(eyeOffsetX + x * CELL_SIZE, eyeOffsetY + y * CELL_SIZE, eyeSize, eyeSize);
          ctx.fillRect(eyeOffsetX + (direction === 'left' ? eyeSize : 0) + x * CELL_SIZE, eyeOffsetY + y * CELL_SIZE, eyeSize, eyeSize);
        } else {
          // Body
          ctx.fillStyle = '#27ae60'; // Darker green body
          ctx.fillRect(x * CELL_SIZE + 1, y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
        }
      }

      // Draw food
      const [fx, fy] = food;
      ctx.fillStyle = '#e74c3c'; // Red food
      ctx.beginPath();
      const centerX = fx * CELL_SIZE + CELL_SIZE / 2;
      const centerY = fy * CELL_SIZE + CELL_SIZE / 2;
      const radius = CELL_SIZE / 2 - 4;
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.fill();
    }

    function updateScore() {
      scoreEl.textContent = `Score: ${score}`;
    }

    // Public API exposed on window.game
    window.game = {
      w: GRID_SIZE,
      h: GRID_SIZE,

      reset() {
        clearInterval(gameInterval);
        gameInterval = null;
        isRunning = false;
        isPaused = false;
        gameOver = false;
        initGame();
        draw();
      },

      tick() {
        if (!isRunning) {
          // If not running, start a one-time tick
          gameTick();
        } else if (isPaused) {
          // If paused, do nothing but return immediately
        } else {
          // Normal execution
          gameTick();
        }
      },

      setDir(dir) {
        const validDirs = ['up', 'down', 'left', 'right'];
        if (!validDirs.includes(dir)) return;

        // Prevent 180-degree reversals
        const opposites = {
          'up': 'down',
          'down': 'up',
          'left': 'right',
          'right': 'left'
        };

        if (opposites[dir] !== direction) {
          nextDirection = dir;
        }
      },

      setFood(x, y) {
        // Set food at specified coordinates
        if (x >= 0 && x < GRID_SIZE && y >= 0 && y < GRID_SIZE) {
          // Check if position is on the snake
          const onSnake = snake.some(segment => segment[0] === x && segment[1] === y);
          if (!onSnake) {
            food = [x, y];
            draw();
          }
        }
      },

      snake() {
        return snake.map(pos => [...pos]);
      },

      food() {
        return [...food];
      },

      alive() {
        return !gameOver;
      },

      score() {
        return score;
      }
    };

    // Event listeners
    startBtn.addEventListener('click', () => startGame());
    pauseBtn.addEventListener('click', () => pauseGame());
    resetBtn.addEventListener('click', () => resetGame());

    document.addEventListener('keydown', (e) => {
      if (!isRunning && !gameOver && e.key.startsWith('Arrow')) return;

      switch (e.key) {
        case 'ArrowUp':
          window.game.setDir('up');
          break;
        case 'ArrowDown':
          window.game.setDir('down');
          break;
        case 'ArrowLeft':
          window.game.setDir('left');
          break;
        case 'ArrowRight':
          window.game.setDir('right');
          break;
      }
    });

    // Initialize and draw the game board on load
    initGame();
  </script>
</body>
</html>
